export const getMarkAsAnswerUrl = (id: number,
    params: MarkAsAnswerParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/discussions/replies/${id}/answer?${stringifiedParams}` : `/discussions/replies/${id}/answer`
}

